import os
import json
import threading
from typing import List, Optional, Dict, Any, Set, Tuple
from datetime import datetime
from pathlib import Path
import logging

from SSI_V5.ingestion.result_models import MatchResult


# Konfiguracja logowania
logger = logging.getLogger(__name__)


class MemoryError(Exception):
    """Wyjatek dla bledow pamieci"""
    pass


class MatchResultMemory:
    """
    Pamiec dla wynikow meczow.
    
    Odpowiedzialna za:
    - Zapis i odczyt wynikow
    - Indexowanie po druzynach
    - Wyszukiwanie
    - Trwalosc danych
    """
    
    # Domyslna sciezka do pliku storage
    DEFAULT_STORAGE_PATH = "data/match_results.json"
    
    def __init__(self, storage_path: Optional[str] = None):
        """
        Inicjalizacja pamieci.
        
        Args:
            storage_path: Sciezka do pliku JSON (opcjonalnie)
        """
        self.storage_path = storage_path or self.DEFAULT_STORAGE_PATH
        self._results: Dict[str, MatchResult] = {}
        self._index: Dict[str, Set[str]] = {
            'home_team': set(),
            'away_team': set(),
            'match_key': set(),
            'date': set(),
            'source': set()
        }
        self._lock = threading.RLock()
        self._loaded = False
        self._modified = False
        
        # Tworzymy katalog jesli nie istnieje
        storage_dir = os.path.dirname(self.storage_path)
        if storage_dir and not os.path.exists(storage_dir):
            os.makedirs(storage_dir, exist_ok=True)
    
    def load(self) -> int:
        """
        Wczytuje dane z pliku JSON.
        
        Returns:
            Liczba zaladowanych wynikow
        """
        with self._lock:
            if self._loaded:
                return len(self._results)
            
            if not os.path.exists(self.storage_path):
                logger.info(f"Storage file not found: {self.storage_path}, starting with empty memory")
                self._loaded = True
                return 0
            
            try:
                with open(self.storage_path, 'r', encoding='utf-8') as f:
                    content = f.read().strip()
                    if not content:
                        # Pusty plik - zaczynamy z pustą pamięcią
                        self._loaded = True
                        return 0
                    data = json.loads(content)
            except json.JSONDecodeError as e:
                logger.error(f"Failed to parse JSON: {str(e)}")
                raise MemoryError(f"Invalid JSON format: {str(e)}")
            except Exception as e:
                logger.error(f"Failed to load storage: {str(e)}")
                raise MemoryError(f"Failed to load storage: {str(e)}")
            
            # Konwersja danych do obiektow MatchResult
            self._results = {}
            for match_id, match_data in data.get('results', {}).items():
                try:
                    match_result = MatchResult.from_dict(match_data)
                    self._results[match_id] = match_result
                    self._update_index(match_result)
                except Exception as e:
                    logger.error(f"Failed to load match {match_id}: {str(e)}")
                    continue
            
            self._loaded = True
            self._modified = False
            
            logger.info(f"Loaded {len(self._results)} match results from {self.storage_path}")
            return len(self._results)
    
    def save(self, force: bool = False) -> bool:
        """
        Zapisuje dane do pliku JSON.
        
        Args:
            force: Wymusz zapis nawet jesli nie bylo modyfikacji
            
        Returns:
            True jesli zapis sie powiodl
        """
        with self._lock:
            if not self._modified and not force:
                logger.debug("No changes to save")
                return False
            
            try:
                data = {
                    'results': {match_id: match.to_dict() for match_id, match in self._results.items()},
                    'metadata': {
                        ' saved_at': datetime.now().isoformat(),
                        'count': len(self._results)
                    }
                }
                
                with open(self.storage_path, 'w', encoding='utf-8') as f:
                    json.dump(data, f, indent=2, ensure_ascii=False)
                
                self._modified = False
                logger.info(f"Saved {len(self._results)} match results to {self.storage_path}")
                return True
                
            except Exception as e:
                logger.error(f"Failed to save storage: {str(e)}")
                raise MemoryError(f"Failed to save storage: {str(e)}")
    
    def auto_save(self) -> bool:
        """Automatycznie zapisuje jesli byly zmiany"""
        with self._lock:
            if self._modified:
                return self.save()
            return False
    
    def save_result(self, match_result: MatchResult) -> str:
        """
        Zapisuje pojedynczy wynik.
        
        Args:
            match_result: Obiekt MatchResult do zapisania
            
        Returns:
            match_id zapisanego wyniku
        """
        with self._lock:
            # Sprawdzamy czy juz exists
            existing_id = self._find_match_id(match_result)
            
            if existing_id:
                # Aktualizujemy istniejacy
                self._results[existing_id] = match_result
                logger.info(f"Updated existing match result: {existing_id}")
            else:
                # Dodajemy nowy
                self._results[match_result.match_id] = match_result
                self._update_index(match_result)
                self._modified = True
                logger.info(f"Added new match result: {match_result.match_id}")
            
            self._modified = True
            return match_result.match_id
    
    def save_results(self, match_results: List[MatchResult]) -> Dict[str, str]:
        """
        Zapisuje liste wynikow.
        
        Args:
            match_results: Lista MatchResult do zapisania
            
        Returns:
            Slownik: {match_id: status}
        """
        with self._lock:
            result_map = {}
            
            for match_result in match_results:
                try:
                    match_id = self.save_result(match_result)
                    result_map[match_id] = "saved"
                except Exception as e:
                    result_map[match_result.match_id] = f"error: {str(e)}"
                    logger.error(f"Failed to save match result: {str(e)}")
            
            self._modified = True
            return result_map
    
    def get_result(self, match_id: str) -> Optional[MatchResult]:
        """
        Pobiera wynik po ID.
        
        Args:
            match_id: ID meczu
            
        Returns:
            MatchResult lub None
        """
        with self._lock:
            self._ensure_loaded()
            return self._results.get(match_id)
    
    def get_all_results(self) -> List[MatchResult]:
        """
        Pobiera wszystkie wyniki.
        
        Returns:
            Lista wszystkich MatchResult
        """
        with self._lock:
            self._ensure_loaded()
            return list(self._results.values())
    
    def get_results_by_team(self, team_name: str) -> List[MatchResult]:
        """
        Pobiera wyniki dla danej druzyny.
        
        Args:
            team_name: Nazwa druzyny
            
        Returns:
            Lista MatchResult z udzialem druzyny
        """
        with self._lock:
            self._ensure_loaded()
            
            team_name = team_name.strip().lower()
            results = []
            
            for match_result in self._results.values():
                if (match_result.home_team.strip().lower() == team_name or
                    match_result.away_team.strip().lower() == team_name):
                    results.append(match_result)
            
            return results
    
    def get_results_by_date(self, date_str: str) -> List[MatchResult]:
        """
        Pobiera wyniki z danego dnia.
        
        Args:
            date_str: Data w formacie YYYY-MM-DD
            
        Returns:
            Lista MatchResult z danego dnia
        """
        with self._lock:
            self._ensure_loaded()
            
            target_date = date_str.strip()
            results = []
            
            for match_result in self._results.values():
                created_date = match_result.created_at.strftime('%Y-%m-%d')
                if created_date == target_date:
                    results.append(match_result)
            
            return results
    
    def search_match(self, home_team: str, away_team: str, date: Optional[str] = None) -> Optional[MatchResult]:
        """
        Wyszukuje konkretny mecz.
        
        Args:
            home_team: Nazwa gospodarzy
            away_team: Nazwa gosci
            date: Opcjonalna data
            
        Returns:
            MatchResult lub None
        """
        with self._lock:
            self._ensure_loaded()
            
            home_team = home_team.strip().lower()
            away_team = away_team.strip().lower()
            
            for match_result in self._results.values():
                if (match_result.home_team.strip().lower() == home_team and
                    match_result.away_team.strip().lower() == away_team):
                    
                    if date:
                        created_date = match_result.created_at.strftime('%Y-%m-%d')
                        if created_date == date:
                            return match_result
                    else:
                        return match_result
            
            # Spróbujmy zamienic drużyny
            for match_result in self._results.values():
                if (match_result.home_team.strip().lower() == away_team and
                    match_result.away_team.strip().lower() == home_team):
                    
                    if date:
                        created_date = match_result.created_at.strftime('%Y-%m-%d')
                        if created_date == date:
                            return match_result
                    else:
                        return match_result
            
            return None
    
    def delete_result(self, match_id: str) -> bool:
        """
        Usuwa wynik z pamieci.
        
        Args:
            match_id: ID meczu do usuniecia
            
        Returns:
            True jesli usunieto
        """
        with self._lock:
            if match_id in self._results:
                match_result = self._results[match_id]
                self._remove_from_index(match_result)
                del self._results[match_id]
                self._modified = True
                logger.info(f"Deleted match result: {match_id}")
                return True
            return False
    
    def clear(self) -> None:
        """Czysci pamiec"""
        with self._lock:
            self._results.clear()
            self._index = {
                'home_team': set(),
                'away_team': set(),
                'match_key': set(),
                'date': set(),
                'source': set()
            }
            self._modified = True
            logger.info("Cleared match result memory")
    
    def count(self) -> int:
        """Zwraca liczbe wynikow w pamieci"""
        with self._lock:
            self._ensure_loaded()
            return len(self._results)
    
    def get_statistics(self) -> Dict[str, Any]:
        """
        Zwraca statystyki pamieci.
        
        Returns:
            Slownik ze statystykami
        """
        with self._lock:
            self._ensure_loaded()
            
            return {
                'total_results': len(self._results),
                'unique_teams': len(self._index['home_team'].union(self._index['away_team'])),
                'unique_match_keys': len(self._index['match_key']),
                'sources': len(self._index['source']),
                'loaded': self._loaded,
                'modified': self._modified
            }
    
    def get_team_statistics(self, team_name: str) -> Dict[str, Any]:
        """
        Zwraca statystyki dla druzyny.
        
        Args:
            team_name: Nazwa druzyny
            
        Returns:
            Slownik ze statystykami druzyny
        """
        with self._lock:
            self._ensure_loaded()
            
            results = self.get_results_by_team(team_name)
            
            if not results:
                return {'team': team_name, 'matches': 0}
            
            wins = 0
            draws = 0
            losses = 0
            goals_for = 0
            goals_against = 0
            
            for match_result in results:
                if match_result.home_team.strip().lower() == team_name.strip().lower():
                    # Druzyna jako gospodarz
                    if match_result.is_home_win:
                        wins += 1
                    elif match_result.is_draw:
                        draws += 1
                    else:
                        losses += 1
                    goals_for += match_result.home_goals
                    goals_against += match_result.away_goals
                else:
                    # Druzyna jako gosc
                    if match_result.is_away_win:
                        wins += 1
                    elif match_result.is_draw:
                        draws += 1
                    else:
                        losses += 1
                    goals_for += match_result.away_goals
                    goals_against += match_result.home_goals
            
            return {
                'team': team_name,
                'matches': len(results),
                'wins': wins,
                'draws': draws,
                'losses': losses,
                'goals_for': goals_for,
                'goals_against': goals_against,
                'goal_difference': goals_for - goals_against
            }
    
    def _ensure_loaded(self):
        """Upewnia sie ze dane sa zaladowane"""
        if not self._loaded:
            self.load()
    
    def _find_match_id(self, match_result: MatchResult) -> Optional[str]:
        """Znajduje ID pasa match_result"""
        match_key = match_result.get_match_key()
        
        for match_id, existing in self._results.items():
            if existing.get_match_key() == match_key:
                return match_id
        
        return None
    
    def _update_index(self, match_result: MatchResult):
        """Aktualizuje indexy"""
        self._index['home_team'].add(match_result.home_team.strip().lower())
        self._index['away_team'].add(match_result.away_team.strip().lower())
        self._index['match_key'].add(match_result.get_match_key())
        self._index['source'].add(match_result.source)
        self._index['date'].add(match_result.created_at.strftime('%Y-%m-%d'))
    
    def _remove_from_index(self, match_result: MatchResult):
        """Usuwa z indexow"""
        # Usuwamy z indexow (na razie nie implementuje, bo to wymagaloby bardziej kompletnillogiki)
        pass


# Instancja globalna (singleton)
_match_result_memory: Optional[MatchResultMemory] = None


def get_match_result_memory(storage_path: Optional[str] = None) -> MatchResultMemory:
    """
    Zwraca instancje MatchResultMemory (singleton).
    
    Args:
        storage_path: Sciezka do pliku storage (opcjonalnie)
        
    Returns:
        Instancja MatchResultMemory
    """
    global _match_result_memory
    
    if _match_result_memory is None:
        _match_result_memory = MatchResultMemory(storage_path)
        _match_result_memory.load()
    
    return _match_result_memory


def reset_match_result_memory():
    """Resetuje singleton MatchResultMemory"""
    global _match_result_memory
    
    if _match_result_memory is not None:
        _match_result_memory.save()
        _match_result_memory = None
